14	export function RoomsPage() {
15	  const [pageIndex, setPageIndex] = useState(0);
16	  const [rowsPerPage, setRowsPerPage] = useState(DEFAULT_PAGE_SIZE);
17	  const [result, setResult] = useState<PagedRoomsDto | null>(null);
18	  const [loading, setLoading] = useState(true);
19	  const [error, setError] = useState<string | null>(null);
20	
21	  useEffect(() => {
22	    let active = true;
23	    setLoading(true);
24	    setError(null);
25	    listRooms(pageIndex + 1, rowsPerPage)
26	      .then((data) => active && setResult(data))
27	      .catch((e: unknown) => active && setError(e instanceof Error ? e.message : String(e)))
28	      .finally(() => active && setLoading(false));
29	    return () => {
30	      active = false;
31	    };
32	  }, [pageIndex, rowsPerPage]);
33	
34	  const handleRowsPerPageChange = (event: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
35	    setRowsPerPage(Number(event.target.value));
36	    setPageIndex(0);
37	  };
38	
39	  return (
40	    <>
41	      <Typography variant="h4" component="h1" gutterBottom>
42	        Rooms
43	      </Typography>
44	      {loading && <LinearProgress aria-label="Loading rooms" />}
45	      {error && <Alert severity="error">{error}</Alert>}
46	      {result && !error && (
47	        <Paper>
48	          <RoomsTable rooms={result.items} />
49	          <TablePagination
50	            component="div"
51	            count={result.total}
52	            page={pageIndex}
53	            onPageChange={(_, nextPageIndex) => setPageIndex(nextPageIndex)}
54	            rowsPerPage={rowsPerPage}
55	            rowsPerPageOptions={ROWS_PER_PAGE_OPTIONS}
56	            onRowsPerPageChange={handleRowsPerPageChange}
57	          />
58	        </Paper>
59	      )}
60	    </>
61	  );
62	}
