import { ConfirmationStatusEnum } from '@roombook/contract';
import type { BookingDto, CreateBookingDto, PagedBookingsDto } from '@roombook/contract';
import { apiClient } from './api-client';
import { createBooking, deleteBooking, listBookings, updateBooking } from './booking.service';

jest.mock('./api-client', () => ({
  apiClient: { get: jest.fn(), post: jest.fn(), patch: jest.fn(), delete: jest.fn() },
}));

const mockedGet = apiClient.get as jest.Mock;
const mockedPost = apiClient.post as jest.Mock;
const mockedPatch = apiClient.patch as jest.Mock;
const mockedDelete = apiClient.delete as jest.Mock;

const ROOM_ID = '00000000-0000-4000-8000-000000000001';
const BOOKING_ID = '11111111-0000-4000-8000-000000000001';
const IDEMPOTENCY_KEY = '22222222-0000-4000-8000-000000000001';

const booking: BookingDto = {
  id: BOOKING_ID,
  roomId: ROOM_ID,
  title: 'Planning',
  organizerEmail: 'ann@example.com',
  startsAt: '2030-01-01T09:30:00.000Z',
  endsAt: '2030-01-01T10:30:00.000Z',
  confirmationStatus: ConfirmationStatusEnum.PENDING,
  confirmationAttempts: 0,
  createdAt: '2029-12-01T00:00:00.000Z',
  updatedAt: '2029-12-01T00:00:00.000Z',
};

describe('booking.service', () => {
  beforeEach(() => jest.resetAllMocks());

  describe('listBookings', () => {
    const body: PagedBookingsDto = { items: [booking], total: 1, page: 2, limit: 5 };

    it('requests GET /bookings with page and limit only when no room is given', async () => {
      mockedGet.mockResolvedValue({ data: body });

      const result = await listBookings(2, 5);

      expect(mockedGet).toHaveBeenCalledWith('/bookings', { params: { page: 2, limit: 5 } });
      expect(mockedGet.mock.calls[0][1].params).not.toHaveProperty('roomId');
      expect(result).toEqual(body);
    });

    it('adds roomId to the query when a room is given', async () => {
      mockedGet.mockResolvedValue({ data: body });

      await listBookings(1, 10, ROOM_ID);

      expect(mockedGet).toHaveBeenCalledWith('/bookings', { params: { page: 1, limit: 10, roomId: ROOM_ID } });
    });
  });

  describe('createBooking', () => {
    it('requests POST /bookings with the body and the Idempotency-Key header', async () => {
      const payload: CreateBookingDto = {
        roomId: ROOM_ID,
        title: 'Planning',
        organizerEmail: 'ann@example.com',
        startsAt: '2030-01-01T09:30:00.000Z',
        endsAt: '2030-01-01T10:30:00.000Z',
      };
      mockedPost.mockResolvedValue({ data: booking });

      const result = await createBooking(payload, IDEMPOTENCY_KEY);

      expect(mockedPost).toHaveBeenCalledWith('/bookings', payload, {
        headers: { 'Idempotency-Key': IDEMPOTENCY_KEY },
      });
      expect(result).toEqual(booking);
    });
  });

  describe('updateBooking', () => {
    it('requests PATCH /bookings/:id with the changes', async () => {
      const changes = { title: 'Retro' };
      mockedPatch.mockResolvedValue({ data: { ...booking, title: 'Retro' } });

      const result = await updateBooking(BOOKING_ID, changes);

      expect(mockedPatch).toHaveBeenCalledWith(`/bookings/${BOOKING_ID}`, changes);
      expect(result.title).toBe('Retro');
    });
  });

  describe('deleteBooking', () => {
    it('requests DELETE /bookings/:id', async () => {
      mockedDelete.mockResolvedValue({ data: '' });

      await expect(deleteBooking(BOOKING_ID)).resolves.toBeUndefined();

      expect(mockedDelete).toHaveBeenCalledWith(`/bookings/${BOOKING_ID}`);
    });
  });

  it('propagates a rejected request', async () => {
    const failure = new Error('boom');
    mockedGet.mockRejectedValue(failure);

    await expect(listBookings(1, 10)).rejects.toBe(failure);
  });
});

import { formatUtcDateTime, inputValueToIsoUtc, isoToInputValue } from './booking-time-format';

describe('booking-time-format', () => {
  it('renders an ISO time as YYYY-MM-DD HH:mm in UTC', () => {
    expect(formatUtcDateTime('2030-01-01T09:30:00.000Z')).toBe('2030-01-01 09:30');
  });

  it('renders an ISO time with an offset in UTC', () => {
    expect(formatUtcDateTime('2030-01-01T01:30:00+02:00')).toBe('2029-12-31 23:30');
  });

  it('turns an ISO time into a datetime-local input value in UTC', () => {
    expect(isoToInputValue('2030-01-01T09:30:00.000Z')).toBe('2030-01-01T09:30');
  });

  it('turns a datetime-local input value into an ISO UTC time', () => {
    expect(inputValueToIsoUtc('2030-01-01T09:30')).toBe('2030-01-01T09:30:00.000Z');
  });
});

import { ApiRouteEnum, IDEMPOTENCY_KEY_HEADER } from '@roombook/contract';
import type {
  BookingDto,
  CreateBookingDto,
  ListBookingsQueryDto,
  PagedBookingsDto,
  UpdateBookingDto,
} from '@roombook/contract';
import { apiClient } from './api-client';

const BOOKINGS_PATH = `/${ApiRouteEnum.BOOKINGS}`;

export const listBookings = async (page: number, limit: number, roomId?: string): Promise<PagedBookingsDto> => {
  const params: ListBookingsQueryDto = roomId ? { page, limit, roomId } : { page, limit };
  const { data } = await apiClient.get<PagedBookingsDto>(BOOKINGS_PATH, { params });
  return data;
};

export const createBooking = async (booking: CreateBookingDto, idempotencyKey: string): Promise<BookingDto> => {
  const { data } = await apiClient.post<BookingDto>(BOOKINGS_PATH, booking, {
    headers: { [IDEMPOTENCY_KEY_HEADER]: idempotencyKey },
  });
  return data;
};

export const updateBooking = async (id: string, changes: UpdateBookingDto): Promise<BookingDto> => {
  const { data } = await apiClient.patch<BookingDto>(`${BOOKINGS_PATH}/${id}`, changes);
  return data;
};

export const deleteBooking = async (id: string): Promise<void> => {
  await apiClient.delete(`${BOOKINGS_PATH}/${id}`);
};

const INPUT_VALUE_LENGTH = 'YYYY-MM-DDTHH:mm'.length;

export const isoToInputValue = (iso: string): string => new Date(iso).toISOString().slice(0, INPUT_VALUE_LENGTH);

export const formatUtcDateTime = (iso: string): string => isoToInputValue(iso).replace('T', ' ');

export const inputValueToIsoUtc = (inputValue: string): string => new Date(`${inputValue}Z`).toISOString();

import { ConfirmationStatusEnum } from '@roombook/contract';
import type { BookingDto, RoomDto } from '@roombook/contract';

export const testRooms: RoomDto[] = Array.from({ length: 12 }, (_, index) => {
  const number = String(index + 1).padStart(2, '0');
  return { id: `00000000-0000-4000-8000-0000000000${number}`, name: `Room ${number}`, capacity: (index + 1) * 2 };
});

export const buildTestBooking = (number: number, roomId: string = testRooms[0].id): BookingDto => {
  const suffix = String(number).padStart(2, '0');
  return {
    id: `11111111-0000-4000-8000-0000000000${suffix}`,
    roomId,
    title: `Booking ${suffix}`,
    organizerEmail: `organizer${suffix}@example.com`,
    startsAt: `2030-01-${suffix}T09:30:00.000Z`,
    endsAt: `2030-01-${suffix}T10:30:00.000Z`,
    confirmationStatus: ConfirmationStatusEnum.PENDING,
    confirmationAttempts: 0,
    createdAt: '2029-12-01T00:00:00.000Z',
    updatedAt: '2029-12-01T00:00:00.000Z',
  };
};

import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ConfirmationStatusEnum } from '@roombook/contract';
import type { BookingDto } from '@roombook/contract';
import { buildTestBooking, testRooms } from './booking-test-data';
import { BookingsTable } from './bookings-table';

const UNKNOWN_ROOM_ID = '99999999-0000-4000-8000-000000000099';

const bookings: BookingDto[] = [
  buildTestBooking(1),
  { ...buildTestBooking(2, UNKNOWN_ROOM_ID), confirmationStatus: ConfirmationStatusEnum.SENT },
];

const renderTable = (items: BookingDto[]) => {
  const onEdit = jest.fn();
  const onDelete = jest.fn();
  render(<BookingsTable bookings={items} rooms={testRooms} onEdit={onEdit} onDelete={onDelete} />);
  const table = screen.getByRole('table', { name: 'Bookings' });
  return { onEdit, onDelete, table, bodyRows: within(table).getAllByRole('row').slice(1) };
};

describe('BookingsTable', () => {
  it('renders the six columns with UTC in the start and end headers', () => {
    const { table } = renderTable(bookings);

    ['Title', 'Room', 'Organizer', 'Start (UTC)', 'End (UTC)', 'Confirmation'].forEach((name) =>
      expect(within(table).getByRole('columnheader', { name })).toBeInTheDocument(),
    );
  });

  it('renders a row per booking with the room name and times as YYYY-MM-DD HH:mm', () => {
    const { bodyRows } = renderTable(bookings);

    expect(bodyRows).toHaveLength(2);
    const firstRow = within(bodyRows[0]);
    expect(firstRow.getByText('Booking 01')).toBeInTheDocument();
    expect(firstRow.getByText('Room 01')).toBeInTheDocument();
    expect(firstRow.getByText('organizer01@example.com')).toBeInTheDocument();
    expect(firstRow.getByText('2030-01-01 09:30')).toBeInTheDocument();
    expect(firstRow.getByText('2030-01-01 10:30')).toBeInTheDocument();
    expect(firstRow.getByText('PENDING')).toBeInTheDocument();
    expect(within(bodyRows[1]).getByText('SENT')).toBeInTheDocument();
  });

  it('shows the room id when the room is not in the room list', () => {
    const { bodyRows } = renderTable(bookings);

    expect(within(bodyRows[1]).getByText(UNKNOWN_ROOM_ID)).toBeInTheDocument();
  });

  it('renders the empty message when there are no bookings', () => {
    const { bodyRows } = renderTable([]);

    expect(bodyRows).toHaveLength(1);
    expect(within(bodyRows[0]).getByText('No bookings found.')).toBeInTheDocument();
  });

  it('calls back with the booking of the row whose edit or delete action is used', async () => {
    const user = userEvent.setup();
    const { onEdit, onDelete } = renderTable(bookings);

    await user.click(screen.getByRole('button', { name: 'Edit Booking 02' }));
    await user.click(screen.getByRole('button', { name: 'Delete Booking 01' }));

    expect(onEdit).toHaveBeenCalledTimes(1);
    expect(onEdit).toHaveBeenCalledWith(bookings[1]);
    expect(onDelete).toHaveBeenCalledTimes(1);
    expect(onDelete).toHaveBeenCalledWith(bookings[0]);
  });
});

import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { testRooms } from './booking-test-data';
import { BookingRoomFilter } from './booking-room-filter';

describe('BookingRoomFilter', () => {
  it('offers "All rooms" and every room name, with "All rooms" selected for an empty value', () => {
    render(<BookingRoomFilter rooms={testRooms} roomId="" onChange={jest.fn()} />);

    const filter = screen.getByLabelText('Filter by room');
    const options = within(filter).getAllByRole('option');
    expect(options.map((option) => option.textContent)).toEqual(['All rooms', ...testRooms.map((room) => room.name)]);
    expect(within(filter).getByRole<HTMLOptionElement>('option', { name: 'All rooms' }).selected).toBe(true);
  });

  it('shows the given room as selected', () => {
    render(<BookingRoomFilter rooms={testRooms} roomId={testRooms[2].id} onChange={jest.fn()} />);

    expect(screen.getByLabelText('Filter by room')).toHaveValue(testRooms[2].id);
  });

  it('calls back with the chosen room id, and with an empty value for "All rooms"', async () => {
