import { ErrorCodeEnum } from '@roombook/contract';
import { isErrorResponse } from './error-response.guard';

describe('isErrorResponse', () => {
  it('accepts an object with the three error fields', () => {
    expect(isErrorResponse({ statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'x' })).toBe(true);
  });

  it.each([
    ['statusCode', { errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'x' }],
    ['errorCode', { statusCode: 404, message: 'x' }],
    ['message', { statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND }],
  ])('rejects an object without %s', (_field, value) => {
    expect(isErrorResponse(value)).toBe(false);
  });

  it('rejects a field of the wrong type', () => {
    expect(isErrorResponse({ statusCode: '404', errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'x' })).toBe(false);
  });

  it.each([null, undefined, 'NOT_FOUND.ROOM', 404])('rejects the non-object %p', (value) => {
    expect(isErrorResponse(value)).toBe(false);
  });
});

import { ErrorResponseDto } from '@roombook/contract';

export const isErrorResponse = (value: unknown): value is ErrorResponseDto => {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const candidate = value as Record<string, unknown>;
  return (
    typeof candidate['statusCode'] === 'number' &&
    typeof candidate['errorCode'] === 'string' &&
    typeof candidate['message'] === 'string'
  );
};

