import { useEffect, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';
import { v4 as uuidv4 } from 'uuid';
import Alert from '@mui/material/Alert';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Grid from '@mui/material/Grid';
import TextField from '@mui/material/TextField';
import Typography from '@mui/material/Typography';
import { BOOKING_TITLE_MAX_LENGTH } from '@roombook/contract';
import type { CreateBookingDto, RoomDto } from '@roombook/contract';
import { createBooking } from '../../services/booking.service';
import { inputValueToIsoUtc, isEndAfterStart } from './booking-time-format';

const EMPTY_VALUES: CreateBookingDto = { roomId: '', title: '', organizerEmail: '', startsAt: '', endsAt: '' };
const SHRUNK_LABEL = { shrink: true };

type BookingCreateFormProps = {
  rooms: RoomDto[];
  onCreated: () => void;
};

export function BookingCreateForm({ rooms, onCreated }: BookingCreateFormProps) {
  const { register, handleSubmit, reset, watch, formState } = useForm<CreateBookingDto>({
    defaultValues: EMPTY_VALUES,
  });
  const { errors, isSubmitting } = formState;
  const [submitError, setSubmitError] = useState<string | null>(null);
  const idempotencyKeyRef = useRef<string | null>(null);

  useEffect(() => {
    const subscription = watch(() => {
      idempotencyKeyRef.current = null;
    });
    return () => subscription.unsubscribe();
  }, [watch]);

  const onSubmit = async (values: CreateBookingDto) => {
    setSubmitError(null);
    idempotencyKeyRef.current ??= uuidv4();
    try {
      await createBooking(
        { ...values, startsAt: inputValueToIsoUtc(values.startsAt), endsAt: inputValueToIsoUtc(values.endsAt) },
        idempotencyKeyRef.current,
      );
    } catch (e: unknown) {
      setSubmitError(e instanceof Error ? e.message : String(e));
      return;
    }
    idempotencyKeyRef.current = null;
    reset();
    onCreated();
  };

  return (
    <Box component="form" aria-labelledby="booking-create-heading" noValidate onSubmit={handleSubmit(onSubmit)}>
      <Typography id="booking-create-heading" variant="h6" component="h2" gutterBottom>
        New booking
      </Typography>
      {submitError && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {submitError}
        </Alert>
      )}
      <Grid container spacing={2}>
        <Grid item xs={12} sm={6}>
          <TextField
            id="booking-create-room"
            select
            fullWidth
            label="Room"
            SelectProps={{ native: true }}
            InputLabelProps={SHRUNK_LABEL}
            inputProps={register('roomId', { required: 'Room is required' })}
            error={Boolean(errors.roomId)}
            helperText={errors.roomId?.message}
          >
            <option value="">Choose a room</option>
            {rooms.map((room) => (
              <option key={room.id} value={room.id}>
                {room.name}
              </option>
            ))}
          </TextField>
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            id="booking-create-title"
            fullWidth
            label="Title"
            InputLabelProps={SHRUNK_LABEL}
            inputProps={{ ...register('title', { required: 'Title is required' }), maxLength: BOOKING_TITLE_MAX_LENGTH }}
            error={Boolean(errors.title)}
            helperText={errors.title?.message}
          />
        </Grid>
        <Grid item xs={12} sm={6}>
          <TextField
            id="booking-create-organizer-email"
            fullWidth
            type="email"
            label="Organizer email"
            InputLabelProps={SHRUNK_LABEL}
            inputProps={register('organizerEmail', { required: 'Organizer email is required' })}
            error={Boolean(errors.organizerEmail)}
            helperText={errors.organizerEmail?.message}
          />
        </Grid>
        <Grid item xs={12} sm={3}>
          <TextField
            id="booking-create-starts-at"
            fullWidth
            type="datetime-local"
            label="Start (UTC)"
            InputLabelProps={SHRUNK_LABEL}
            inputProps={register('startsAt', { required: 'Start is required' })}
            error={Boolean(errors.startsAt)}
            helperText={errors.startsAt?.message}
          />
        </Grid>
        <Grid item xs={12} sm={3}>
          <TextField
            id="booking-create-ends-at"
            fullWidth
            type="datetime-local"
            label="End (UTC)"
            InputLabelProps={SHRUNK_LABEL}
            inputProps={register('endsAt', {
              required: 'End is required',
              validate: (endsAt, values) => isEndAfterStart(endsAt, values.startsAt) || 'End must be later than start',
            })}
            error={Boolean(errors.endsAt)}
            helperText={errors.endsAt?.message}
          />
        </Grid>
        <Grid item xs={12}>
          <Button type="submit" variant="contained" disabled={isSubmitting}>
            Create booking
          </Button>
        </Grid>
      </Grid>
    </Box>
  );
}

import { isErrorResponse } from './error-response.guard';

describe('isErrorResponse', () => {
  it('accepts an object with the three error fields', () => {
    expect(isErrorResponse({ statusCode: 404, errorCode: 'NOT_FOUND.ROOM', message: 'x' })).toBe(true);
  });

  it.each([
    ['statusCode', { errorCode: 'NOT_FOUND.ROOM', message: 'x' }],
    ['errorCode', { statusCode: 404, message: 'x' }],
    ['message', { statusCode: 404, errorCode: 'NOT_FOUND.ROOM' }],
  ])('rejects an object without %s', (_field, value) => {
    expect(isErrorResponse(value)).toBe(false);
  });

  it('rejects a field of the wrong type', () => {
    expect(isErrorResponse({ statusCode: '404', errorCode: 'NOT_FOUND.ROOM', message: 'x' })).toBe(false);
  });

  it.each([null, undefined, 'NOT_FOUND.ROOM', 404])('rejects the non-object %p', (value) => {
    expect(isErrorResponse(value)).toBe(false);
  });
});

import { fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ErrorCodeEnum } from '@roombook/contract';
import { ApiError } from '../../services/api-error';
import { updateBooking } from '../../services/booking.service';
import { BookingEditDialog } from './booking-edit-dialog';
import { buildTestBooking } from './booking-test-data';

jest.mock('../../services/booking.service', () => ({ updateBooking: jest.fn() }));

const mockedUpdateBooking = updateBooking as jest.MockedFunction<typeof updateBooking>;

const booking = buildTestBooking(1);

const setup = () => {
  const user = userEvent.setup();
  const onSaved = jest.fn();
  const onClose = jest.fn();
  render(<BookingEditDialog booking={booking} onSaved={onSaved} onClose={onClose} />);
  const dialog = within(screen.getByRole('dialog', { name: 'Edit booking' }));
  return { user, onSaved, onClose, dialog };
};

describe('BookingEditDialog', () => {
  beforeEach(() => {
    mockedUpdateBooking.mockReset();
    mockedUpdateBooking.mockResolvedValue(booking);
  });

  it("is prefilled with the booking's title, start and end", () => {
    const { dialog } = setup();

    expect(dialog.getByLabelText('Title')).toHaveValue('Booking 01');
    expect(dialog.getByLabelText('Start (UTC)')).toHaveValue('2030-01-01T09:30');
    expect(dialog.getByLabelText('End (UTC)')).toHaveValue('2030-01-01T10:30');
  });

  it('sends one update with the new title and the start and end, then reports it saved', async () => {
    const { user, onSaved, dialog } = setup();
    await user.clear(dialog.getByLabelText('Title'));
    await user.type(dialog.getByLabelText('Title'), 'Retro');

    await user.click(dialog.getByRole('button', { name: 'Save' }));

    await waitFor(() => expect(onSaved).toHaveBeenCalledTimes(1));
    expect(mockedUpdateBooking).toHaveBeenCalledTimes(1);
    expect(mockedUpdateBooking).toHaveBeenCalledWith(booking.id, {
      title: 'Retro',
      startsAt: '2030-01-01T09:30:00.000Z',
      endsAt: '2030-01-01T10:30:00.000Z',
    });
  });

  it('sends nothing when cancelled', async () => {
    const { user, onSaved, onClose, dialog } = setup();
    await user.type(dialog.getByLabelText('Title'), ' changed');

    await user.click(dialog.getByRole('button', { name: 'Cancel' }));

    expect(onClose).toHaveBeenCalledTimes(1);
    expect(mockedUpdateBooking).not.toHaveBeenCalled();
    expect(onSaved).not.toHaveBeenCalled();
  });

  it('sends nothing and marks the title when it is empty', async () => {
    const { user, dialog } = setup();
    await user.clear(dialog.getByLabelText('Title'));

    await user.click(dialog.getByRole('button', { name: 'Save' }));

    expect(await dialog.findByText('Title is required')).toBeInTheDocument();
    expect(mockedUpdateBooking).not.toHaveBeenCalled();
  });

  it.each([
    ['equal to', '2030-01-01T09:30'],
    ['earlier than', '2030-01-01T09:00'],
  ])('sends nothing and marks the end when it is %s the start', async (_, endValue) => {
    const { user, onSaved, dialog } = setup();
    fireEvent.change(dialog.getByLabelText('End (UTC)'), { target: { value: endValue } });

    await user.click(dialog.getByRole('button', { name: 'Save' }));

    expect(await dialog.findByText('End must be later than start')).toBeInTheDocument();
    expect(dialog.getByLabelText('End (UTC)')).toBeInvalid();
    expect(mockedUpdateBooking).not.toHaveBeenCalled();
    expect(onSaved).not.toHaveBeenCalled();
  });

  it('shows the API message and keeps the entered values when the update fails', async () => {
    mockedUpdateBooking.mockRejectedValue(
      new ApiError({
        statusCode: 404,
        errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND,
        message: 'Booking 123 was not found',
      }),
    );
    const { user, onSaved, onClose, dialog } = setup();
    await user.type(dialog.getByLabelText('Title'), ' v2');

    await user.click(dialog.getByRole('button', { name: 'Save' }));

    expect(await dialog.findByRole('alert')).toHaveTextContent('Booking 123 was not found');
    expect(dialog.getByLabelText('Title')).toHaveValue('Booking 01 v2');
    expect(onSaved).not.toHaveBeenCalled();
    expect(onClose).not.toHaveBeenCalled();
  });
});

