import { ErrorCodeEnum, PagedBookingsDto } from '@roombook/contract';
import { BOOKING_ID, bookingDto, ROOM_ID, rpcErrorOf } from './testing/booking.fixture';
import { BookingServiceHarness, createBookingServiceHarness } from './testing/booking-service.harness';

describe('BookingService', () => {
  const notFound = expect.objectContaining({ statusCode: 404, errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND });
  let harness: BookingServiceHarness;

  beforeEach(async () => {
    harness = await createBookingServiceHarness();
    harness.bookingRepository.findById.mockResolvedValue(bookingDto());
  });

  it('lists a page of bookings', async () => {
    const paged: PagedBookingsDto = { items: [bookingDto()], total: 1, page: 1, limit: 10 };
    harness.bookingRepository.findPage.mockResolvedValue(paged);

    await expect(harness.service.listBookings({ page: 1, limit: 10, roomId: ROOM_ID })).resolves.toBe(paged);
    expect(harness.bookingRepository.findPage).toHaveBeenCalledWith({ page: 1, limit: 10, roomId: ROOM_ID });
  });

  it('answers an empty page when no booking matches', async () => {
    const paged: PagedBookingsDto = { items: [], total: 0, page: 1, limit: 10 };
    harness.bookingRepository.findPage.mockResolvedValue(paged);

    await expect(harness.service.listBookings({ page: 1, limit: 10 })).resolves.toBe(paged);
  });

  it('finds a booking by id', async () => {
    await expect(harness.service.findBookingById(BOOKING_ID)).resolves.toEqual(bookingDto());
    expect(harness.bookingRepository.findById).toHaveBeenCalledWith(BOOKING_ID);
  });

  it('raises 404 NOT_FOUND.BOOKING for an unknown id', async () => {
    harness.bookingRepository.findById.mockResolvedValue(null);

    expect(await rpcErrorOf(() => harness.service.findBookingById(BOOKING_ID))).toEqual(notFound);
  });

  it('updates the changed title and keeps the stored times', async () => {
    const updated = bookingDto({ title: 'Retro' });
    harness.bookingRepository.update.mockResolvedValue(updated);

    await expect(harness.service.updateBooking({ id: BOOKING_ID, changes: { title: 'Retro' } })).resolves.toBe(
      updated,
    );
    expect(harness.bookingRepository.update).toHaveBeenCalledWith({
      id: BOOKING_ID,
      title: 'Retro',
      startsAt: new Date('2030-01-01T10:00:00.000Z'),
      endsAt: new Date('2030-01-01T11:00:00.000Z'),
    });
  });

  it('updates both times, reading an offset and a zone-less value as UTC instants', async () => {
    harness.bookingRepository.update.mockResolvedValue(bookingDto());

    await harness.service.updateBooking({
      id: BOOKING_ID,
      changes: { startsAt: '2030-02-01T10:00:00+02:00', endsAt: '2030-02-01T09:00:00' },
    });

    expect(harness.bookingRepository.update).toHaveBeenCalledWith({
      id: BOOKING_ID,
      title: 'Planning',
      startsAt: new Date('2030-02-01T08:00:00.000Z'),
      endsAt: new Date('2030-02-01T09:00:00.000Z'),
    });
  });

  it('keeps every stored value for an empty change set', async () => {
    harness.bookingRepository.update.mockResolvedValue(bookingDto());

    await expect(harness.service.updateBooking({ id: BOOKING_ID, changes: {} })).resolves.toEqual(bookingDto());
    expect(harness.bookingRepository.update).toHaveBeenCalledWith({
      id: BOOKING_ID,
      title: 'Planning',
      startsAt: new Date('2030-01-01T10:00:00.000Z'),
      endsAt: new Date('2030-01-01T11:00:00.000Z'),
    });
  });

  it.each([
    ['moves startsAt past the stored endsAt', { startsAt: '2030-01-01T12:00:00Z' }],
    ['moves endsAt onto the stored startsAt', { endsAt: '2030-01-01T10:00:00Z' }],
    ['carries a time that is not an instant', { startsAt: '2030-W01-1' }],
  ])('raises 400 BAD_REQUEST.VALIDATION and stores nothing when an update %s', async (_case, changes) => {
    expect(await rpcErrorOf(() => harness.service.updateBooking({ id: BOOKING_ID, changes }))).toEqual(
      expect.objectContaining({ statusCode: 400, errorCode: ErrorCodeEnum.VALIDATION }),
    );
    expect(harness.bookingRepository.update).not.toHaveBeenCalled();
  });

  it('raises 404 NOT_FOUND.BOOKING when the updated id is unknown', async () => {
    harness.bookingRepository.findById.mockResolvedValue(null);

    expect(await rpcErrorOf(() => harness.service.updateBooking({ id: BOOKING_ID, changes: { title: 'x' } }))).toEqual(
      notFound,
    );
    expect(harness.bookingRepository.update).not.toHaveBeenCalled();
  });

  it('raises 404 NOT_FOUND.BOOKING when the booking is deleted while it is updated', async () => {
    harness.bookingRepository.update.mockResolvedValue(null);

    expect(await rpcErrorOf(() => harness.service.updateBooking({ id: BOOKING_ID, changes: { title: 'x' } }))).toEqual(
      notFound,
    );
  });

  it('deletes a booking', async () => {
    harness.bookingRepository.delete.mockResolvedValue(true);

    await expect(harness.service.deleteBooking(BOOKING_ID)).resolves.toBe(true);
    expect(harness.bookingRepository.delete).toHaveBeenCalledWith(BOOKING_ID);
  });

  it('raises 404 NOT_FOUND.BOOKING when the deleted id is unknown', async () => {
    harness.bookingRepository.delete.mockResolvedValue(false);

    expect(await rpcErrorOf(() => harness.service.deleteBooking(BOOKING_ID))).toEqual(notFound);
  });
});

import { render, screen, waitFor, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ErrorCodeEnum } from '@roombook/contract';
import { ApiError } from '../../services/api-error';
import { listBookings } from '../../services/booking.service';
import { listRooms } from '../../services/room.service';
import { buildTestBooking, pageOfBookings, testRooms } from './booking-test-data';
import { BookingsPage } from './bookings-page';

jest.mock('../../services/booking.service', () => ({ listBookings: jest.fn() }));
jest.mock('../../services/room.service', () => ({ listRooms: jest.fn() }));

const mockedListBookings = listBookings as jest.MockedFunction<typeof listBookings>;
const mockedListRooms = listRooms as jest.MockedFunction<typeof listRooms>;

const ROOM_03_ID = testRooms[2].id;
const seededBookings = Array.from({ length: 12 }, (_, index) =>
  buildTestBooking(index + 1, index < 2 ? ROOM_03_ID : testRooms[0].id),
);

const bodyRows = () => within(screen.getByRole('table', { name: 'Bookings' })).getAllByRole('row').slice(1);

describe('BookingsPage', () => {
  beforeEach(() => {
    mockedListBookings.mockReset();
    mockedListRooms.mockReset();
    mockedListRooms.mockResolvedValue({ items: testRooms, total: testRooms.length, page: 1, limit: 100 });
    mockedListBookings.mockImplementation((page, limit, roomId) =>
      Promise.resolve(pageOfBookings(seededBookings, page, limit, roomId)),
    );
  });

  it('shows a loading indicator, then the heading, the filter, the create form and the rows of page 1', async () => {
    render(<BookingsPage />);

    expect(screen.getByRole('progressbar')).toBeInTheDocument();
    expect(await screen.findByText('Booking 10')).toBeInTheDocument();
    expect(screen.queryByRole('progressbar')).not.toBeInTheDocument();
    expect(screen.getByRole('heading', { level: 1, name: 'Bookings' })).toBeInTheDocument();
    expect(screen.getByLabelText('Filter by room')).toHaveValue('');
    expect(screen.getByRole('button', { name: 'Create booking' })).toBeInTheDocument();
    expect(mockedListRooms).toHaveBeenCalledWith(1, 100);
    expect(mockedListBookings).toHaveBeenCalledWith(1, 10, undefined);
    expect(bodyRows()).toHaveLength(10);
    expect(within(bodyRows()[0]).getByText('Room 03')).toBeInTheDocument();
    expect(within(bodyRows()[0]).getByText('2030-01-01 09:30')).toBeInTheDocument();
  });

  it('fills the filter with "All rooms" and the room names', async () => {
    render(<BookingsPage />);
    await screen.findByText('Booking 10');

    const options = within(screen.getByLabelText('Filter by room')).getAllByRole('option');
    expect(options.map((option) => option.textContent)).toEqual(['All rooms', ...testRooms.map((room) => room.name)]);
  });

  it('shows the empty message when the API answers no bookings', async () => {
    mockedListBookings.mockResolvedValue({ items: [], total: 0, page: 1, limit: 10 });
    render(<BookingsPage />);

    expect(await screen.findByText('No bookings found.')).toBeInTheDocument();
  });

  it('shows the API message and no table when loading the bookings fails', async () => {
    mockedListBookings.mockRejectedValue(
      new ApiError({
        statusCode: 503,
        errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE,
        message: 'Booking service is unavailable',
      }),
    );
    render(<BookingsPage />);

    expect(await screen.findByRole('alert')).toHaveTextContent('Booking service is unavailable');
    expect(screen.queryByRole('table', { name: 'Bookings' })).not.toBeInTheDocument();
    expect(screen.queryByRole('progressbar')).not.toBeInTheDocument();
  });

  it('shows the API message and no table when loading the rooms fails', async () => {
    mockedListRooms.mockRejectedValue(
      new ApiError({
        statusCode: 503,
        errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE,
        message: 'Room service is unavailable',
      }),
    );
    render(<BookingsPage />);

    expect(await screen.findByRole('alert')).toHaveTextContent('Room service is unavailable');
    expect(screen.queryByRole('table', { name: 'Bookings' })).not.toBeInTheDocument();
    expect(screen.queryByRole('progressbar')).not.toBeInTheDocument();
  });

  it('requests page 2 and shows its rows after going to the next page', async () => {
    const user = userEvent.setup();
    render(<BookingsPage />);
    await screen.findByText('Booking 10');

    await user.click(screen.getByRole('button', { name: /next page/i }));

    await waitFor(() => expect(mockedListBookings).toHaveBeenLastCalledWith(2, 10, undefined));
    expect(await screen.findByText('Booking 11')).toBeInTheDocument();
    expect(bodyRows()).toHaveLength(2);
  });

  it('requests page 1 of the chosen room, and drops the filter again for "All rooms"', async () => {
    const user = userEvent.setup();
    render(<BookingsPage />);
    await screen.findByText('Booking 10');
    await user.click(screen.getByRole('button', { name: /next page/i }));
    await screen.findByText('Booking 11');

    await user.selectOptions(screen.getByLabelText('Filter by room'), 'Room 03');

    await waitFor(() => expect(mockedListBookings).toHaveBeenLastCalledWith(1, 10, ROOM_03_ID));
    await waitFor(() => expect(bodyRows()).toHaveLength(2));
    expect(screen.getByText('Booking 01')).toBeInTheDocument();
    expect(screen.getByText('Booking 02')).toBeInTheDocument();

    await user.selectOptions(screen.getByLabelText('Filter by room'), 'All rooms');

    await waitFor(() => expect(mockedListBookings).toHaveBeenLastCalledWith(1, 10, undefined));
    await waitFor(() => expect(bodyRows()).toHaveLength(10));
  });
});

import { PATTERN_METADATA } from '@nestjs/microservices/constants';
import { Test } from '@nestjs/testing';
import { BookingPatternEnum, PagedBookingsDto } from '@roombook/contract';
import { BookingController } from './booking.controller';
import { BookingService } from './booking.service';
import { BOOKING_ID, bookingDto } from './testing/booking.fixture';

const patternOf = (handler: keyof BookingController): unknown =>
  Reflect.getMetadata(PATTERN_METADATA, BookingController.prototype[handler]);

describe('BookingController', () => {
  let controller: BookingController;
  let service: Record<'listBookings' | 'findBookingById' | 'updateBooking' | 'deleteBooking', jest.Mock>;

  beforeEach(async () => {
    service = { listBookings: jest.fn(), findBookingById: jest.fn(), updateBooking: jest.fn(), deleteBooking: jest.fn() };
    const moduleRef = await Test.createTestingModule({
      controllers: [BookingController],
      providers: [{ provide: BookingService, useValue: service }],
    }).compile();
    controller = moduleRef.get(BookingController);
  });

  it('answers the booking list pattern', async () => {
    const paged: PagedBookingsDto = { items: [bookingDto()], total: 1, page: 1, limit: 10 };
    service.listBookings.mockResolvedValue(paged);

    expect(patternOf('listBookings')).toEqual([BookingPatternEnum.LIST]);
    await expect(controller.listBookings({ page: 1, limit: 10 })).resolves.toBe(paged);
    expect(service.listBookings).toHaveBeenCalledWith({ page: 1, limit: 10 });
  });

  it('answers the find booking by id pattern', async () => {
    const booking = bookingDto();
    service.findBookingById.mockResolvedValue(booking);

    expect(patternOf('findBookingById')).toEqual([BookingPatternEnum.FIND_BY_ID]);
    await expect(controller.findBookingById({ id: BOOKING_ID })).resolves.toBe(booking);
    expect(service.findBookingById).toHaveBeenCalledWith(BOOKING_ID);
  });

  it('answers the update booking pattern', async () => {
    const booking = bookingDto({ title: 'Retro' });
    const message = { id: BOOKING_ID, changes: { title: 'Retro' } };
    service.updateBooking.mockResolvedValue(booking);

    expect(patternOf('updateBooking')).toEqual([BookingPatternEnum.UPDATE]);
    await expect(controller.updateBooking(message)).resolves.toBe(booking);
    expect(service.updateBooking).toHaveBeenCalledWith(message);
  });

  it('answers the delete booking pattern', async () => {
    service.deleteBooking.mockResolvedValue(true);

    expect(patternOf('deleteBooking')).toEqual([BookingPatternEnum.DELETE]);
    await expect(controller.deleteBooking({ id: BOOKING_ID })).resolves.toBe(true);
    expect(service.deleteBooking).toHaveBeenCalledWith(BOOKING_ID);
  });
});

