    mockedCreateBooking.mockResolvedValue(buildTestBooking(12));
    const user = await renderLoadedPage();

    await user.selectOptions(screen.getByLabelText('Room'), 'Room 03');
    await user.type(screen.getByLabelText('Title'), 'Planning');
    await user.type(screen.getByLabelText('Organizer email'), 'ann@example.com');
    fireEvent.change(screen.getByLabelText('Start (UTC)'), { target: { value: '2030-01-01T09:30' } });
    fireEvent.change(screen.getByLabelText('End (UTC)'), { target: { value: '2030-01-01T10:30' } });
    await user.click(screen.getByRole('button', { name: 'Create booking' }));

    await waitFor(() => expect(mockedListBookings).toHaveBeenCalledTimes(2));
    expect(mockedCreateBooking).toHaveBeenCalledTimes(1);
    expect(mockedCreateBooking.mock.calls[0][0].roomId).toBe(testRooms[2].id);
    expect(mockedListBookings).toHaveBeenLastCalledWith(1, 10, undefined);
  });

  it('closes the edit dialog and reloads the table after a booking is saved', async () => {
    mockedUpdateBooking.mockImplementation((id, changes) => {
      storedBookings = storedBookings.map((booking) => (booking.id === id ? { ...booking, ...changes } : booking));
      return Promise.resolve(storedBookings[0]);
    });
    const user = await renderLoadedPage();

    await user.click(screen.getByRole('button', { name: 'Edit Booking 01' }));
    const dialog = within(screen.getByRole('dialog', { name: 'Edit booking' }));
    expect(dialog.getByLabelText('Title')).toHaveValue('Booking 01');
    await user.clear(dialog.getByLabelText('Title'));
    await user.type(dialog.getByLabelText('Title'), 'Retro');
    await user.click(dialog.getByRole('button', { name: 'Save' }));

    expect(await screen.findByText('Retro')).toBeInTheDocument();
    expect(mockedUpdateBooking).toHaveBeenCalledWith(storedBookings[0].id, {
      title: 'Retro',
      startsAt: '2030-01-01T09:30:00.000Z',
      endsAt: '2030-01-01T10:30:00.000Z',
    });
    expect(mockedListBookings).toHaveBeenCalledTimes(2);
    await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
  });

  it('sends nothing when the edit dialog is cancelled', async () => {
    const user = await renderLoadedPage();

    await user.click(screen.getByRole('button', { name: 'Edit Booking 01' }));
    await user.click(screen.getByRole('button', { name: 'Cancel' }));

    await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
    expect(mockedUpdateBooking).not.toHaveBeenCalled();
    expect(mockedListBookings).toHaveBeenCalledTimes(1);
  });

  it('deletes the booking and reloads the table after the delete is confirmed', async () => {
    const deletedId = storedBookings[0].id;
    const user = await renderLoadedPage();

    await user.click(screen.getByRole('button', { name: 'Delete Booking 01' }));
    await user.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Delete' }));

    await waitFor(() => expect(screen.queryByText('Booking 01')).not.toBeInTheDocument());
    expect(mockedDeleteBooking).toHaveBeenCalledTimes(1);
    expect(mockedDeleteBooking).toHaveBeenCalledWith(deletedId);
    expect(mockedListBookings).toHaveBeenCalledTimes(2);
    expect(screen.getByText('Booking 11')).toBeInTheDocument();
  });

  it('sends nothing and keeps the row when the delete is declined', async () => {
    const user = await renderLoadedPage();

    await user.click(screen.getByRole('button', { name: 'Delete Booking 01' }));
    await user.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Cancel' }));

    await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument());
    expect(mockedDeleteBooking).not.toHaveBeenCalled();
    expect(mockedListBookings).toHaveBeenCalledTimes(1);
    expect(screen.getByText('Booking 01')).toBeInTheDocument();
  });

  it('shows the API message and keeps the table when the delete fails', async () => {
    mockedDeleteBooking.mockRejectedValue(
      new ApiError({
        statusCode: 404,
        errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND,
        message: 'Booking 123 was not found',
      }),
    );
    const user = await renderLoadedPage();

    await user.click(screen.getByRole('button', { name: 'Delete Booking 01' }));
    await user.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Delete' }));

    expect(await screen.findByRole('alert')).toHaveTextContent('Booking 123 was not found');
    expect(screen.getByRole('table', { name: 'Bookings' })).toBeInTheDocument();
    expect(screen.getByText('Booking 01')).toBeInTheDocument();
  });

  it('goes back one page after deleting the only booking of the last page', async () => {
    const user = await renderLoadedPage();
    await user.click(screen.getByRole('button', { name: /next page/i }));
    await screen.findByText('Booking 11');

    await user.click(screen.getByRole('button', { name: 'Delete Booking 11' }));
    await user.click(within(screen.getByRole('dialog')).getByRole('button', { name: 'Delete' }));

    await waitFor(() => expect(mockedListBookings).toHaveBeenLastCalledWith(1, 10, undefined));
    expect(await screen.findByText('Booking 10')).toBeInTheDocument();
  });
});

import { ExceptionHelper } from '@roombook/backend-common';
import { ErrorCodeEnum } from '@roombook/contract';

const TIME_PART = /[T\s](.*)$/i;
const ZONE_DESIGNATOR = /(Z|[+-]\d{2}(:?\d{2})?)$/i;

export class BookingTimeUtil {
  static toDate(value: string): Date {
    const timePart = TIME_PART.exec(value)?.[1];
    const isZoneLess = timePart !== undefined && !ZONE_DESIGNATOR.test(timePart);
    const date = new Date(isZoneLess ? `${value}Z` : value);
    if (Number.isNaN(date.getTime())) {
      ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, `${value} cannot be resolved to an instant`);
    }
    return date;
  }
}

import { BookingEntity } from '@roombook/backend-common';
import { BookingDto } from '@roombook/contract';

export class BookingMapper {
  static toDto(entity: BookingEntity): BookingDto {
    return {
      id: entity.id,
      roomId: entity.roomId,
      title: entity.title,
      organizerEmail: entity.organizerEmail,
      startsAt: entity.startsAt.toISOString(),
      endsAt: entity.endsAt.toISOString(),
      confirmationStatus: entity.confirmationStatus,
      confirmationAttempts: entity.confirmationAttempts,
      createdAt: entity.createdAt.toISOString(),
      updatedAt: entity.updatedAt.toISOString(),
    };
  }
}

import { Injectable } from '@nestjs/common';
import { ExceptionHelper } from '@roombook/backend-common';
import { ErrorCodeEnum } from '@roombook/contract';

@Injectable()
export class BookingValidator {
  assertTimeOrder(startsAt: Date, endsAt: Date): void {
    if (endsAt.getTime() <= startsAt.getTime()) {
      ExceptionHelper.badRequest(ErrorCodeEnum.VALIDATION, 'endsAt must be later than startsAt');
    }
  }
}

export class UpdateBookingCommand {
  id: string;
  title: string;
  startsAt: Date;
  endsAt: Date;
}

import { Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { BookingEntity } from '@roombook/backend-common';
import { BookingDto, ListBookingsQueryDto, PagedBookingsDto } from '@roombook/contract';
import { Repository } from 'typeorm';
import { BookingMapper } from './booking.mapper';
import { UpdateBookingCommand } from './dto/update-booking.command';

@Injectable()
export class BookingRepository {
  constructor(@InjectRepository(BookingEntity) private readonly bookings: Repository<BookingEntity>) {}

  async findPage(query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
    const [entities, total] = await this.bookings.findAndCount({
      where: query.roomId ? { roomId: query.roomId } : {},
      order: { startsAt: 'ASC', id: 'ASC' },
      skip: (query.page - 1) * query.limit,
      take: query.limit,
    });
    return { items: entities.map(BookingMapper.toDto), total, page: query.page, limit: query.limit };
  }

  async findById(id: string): Promise<BookingDto | null> {
    const entity = await this.bookings.findOneBy({ id });
    return entity ? BookingMapper.toDto(entity) : null;
  }

  async update(command: UpdateBookingCommand): Promise<BookingDto | null> {
    const { id, ...values } = command;
    const result = await this.bookings.update({ id }, values);
    return result.affected ? this.findById(id) : null;
  }

  async delete(id: string): Promise<boolean> {
    const result = await this.bookings.delete({ id });
    return Boolean(result.affected);
  }
}

import { Injectable } from '@nestjs/common';
import { ExceptionHelper } from '@roombook/backend-common';
import {
  BookingDto,
  ErrorCodeEnum,
  ListBookingsQueryDto,
  PagedBookingsDto,
  UpdateBookingMessageDto,
} from '@roombook/contract';
import { BookingTimeUtil } from './booking-time.util';
import { BookingRepository } from './booking.repository';
import { BookingValidator } from './booking.validator';

@Injectable()
export class BookingService {
  constructor(
    private readonly bookingRepository: BookingRepository,
    private readonly bookingValidator: BookingValidator,
  ) {}

  listBookings(query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
    return this.bookingRepository.findPage(query);
  }

  async findBookingById(id: string): Promise<BookingDto> {
    const booking = await this.bookingRepository.findById(id);
    return booking ?? this.raiseNotFound(id);
  }

  async updateBooking(message: UpdateBookingMessageDto): Promise<BookingDto> {
    const { id, changes } = message;
    const stored = await this.findBookingById(id);
    const startsAt = BookingTimeUtil.toDate(changes.startsAt ?? stored.startsAt);
    const endsAt = BookingTimeUtil.toDate(changes.endsAt ?? stored.endsAt);
    this.bookingValidator.assertTimeOrder(startsAt, endsAt);
    const updated = await this.bookingRepository.update({ id, title: changes.title ?? stored.title, startsAt, endsAt });
    return updated ?? this.raiseNotFound(id);
  }

  async deleteBooking(id: string): Promise<boolean> {
    const deleted = await this.bookingRepository.delete(id);
    return deleted || this.raiseNotFound(id);
  }

  private raiseNotFound(id: string): never {
    return ExceptionHelper.notFound(ErrorCodeEnum.BOOKING_NOT_FOUND, `Booking ${id} was not found`);
  }
}

import { Controller } from '@nestjs/common';
import { MessagePattern, Payload } from '@nestjs/microservices';
import {
  BookingDto,
  BookingIdMessageDto,
  BookingPatternEnum,
  ListBookingsQueryDto,
  PagedBookingsDto,
  UpdateBookingMessageDto,
} from '@roombook/contract';
import { BookingService } from './booking.service';

@Controller()
export class BookingController {
  constructor(private readonly bookingService: BookingService) {}

  @MessagePattern(BookingPatternEnum.LIST)
  listBookings(@Payload() query: ListBookingsQueryDto): Promise<PagedBookingsDto> {
    return this.bookingService.listBookings(query);
  }

  @MessagePattern(BookingPatternEnum.FIND_BY_ID)
  findBookingById(@Payload() message: BookingIdMessageDto): Promise<BookingDto> {
    return this.bookingService.findBookingById(message.id);
  }

  @MessagePattern(BookingPatternEnum.UPDATE)
  updateBooking(@Payload() message: UpdateBookingMessageDto): Promise<BookingDto> {
    return this.bookingService.updateBooking(message);
  }

  // A reply must carry a value: the NATS client completes empty on an undefined one.
  @MessagePattern(BookingPatternEnum.DELETE)
  deleteBooking(@Payload() message: BookingIdMessageDto): Promise<boolean> {
    return this.bookingService.deleteBooking(message.id);
  }
}

