import { RpcException } from '@nestjs/microservices';
import { EmptyResponseException } from '@nestjs/microservices/errors/empty-response.exception';
import { Test } from '@nestjs/testing';
import { NATS_CLIENT } from '@roombook/backend-common';
import { ErrorCodeEnum, RoomPatternEnum } from '@roombook/contract';
import { of, throwError } from 'rxjs';
import { RoomLookupClient } from './room-lookup.client';
import { ROOM_ID } from './testing/booking.fixture';

describe('RoomLookupClient', () => {
  let client: RoomLookupClient;
  let send: jest.Mock;

  beforeEach(async () => {
    send = jest.fn();
    const moduleRef = await Test.createTestingModule({
      providers: [RoomLookupClient, { provide: NATS_CLIENT, useValue: { send } }],
    }).compile();
    client = moduleRef.get(RoomLookupClient);
  });

  it('resolves when the room service knows the room', async () => {
    send.mockReturnValue(of({ id: ROOM_ID, name: 'Room 01', capacity: 2 }));

    await expect(client.assertRoomExists(ROOM_ID)).resolves.toBeUndefined();
    expect(send).toHaveBeenCalledWith(RoomPatternEnum.FIND_BY_ID, { id: ROOM_ID });
  });

  it('re-raises the relayed NOT_FOUND.ROOM object as a 404 RpcException', async () => {
    const relayed = { statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'Room was not found' };
    send.mockReturnValue(throwError(() => relayed));

    const error = await client.assertRoomExists(ROOM_ID).catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(RpcException);
    expect((error as RpcException).getError()).toEqual(relayed);
  });

  it('lets 503 UNAVAILABLE.SERVICE pass when the room service does not answer', async () => {
    send.mockReturnValue(throwError(() => new EmptyResponseException(RoomPatternEnum.FIND_BY_ID)));

    const error = await client.assertRoomExists(ROOM_ID).catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(RpcException);
    expect((error as RpcException).getError()).toEqual(
      expect.objectContaining({ statusCode: 503, errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE }),
    );
  });

  it('rethrows any other error unchanged', async () => {
    const unknown = { status: 'error', message: 'Internal server error' };
    send.mockReturnValue(throwError(() => unknown));

    await expect(client.assertRoomExists(ROOM_ID)).rejects.toBe(unknown);
  });
});

import { getQueueToken } from '@nestjs/bullmq';
import { Logger } from '@nestjs/common';
import { Test } from '@nestjs/testing';
import { confirmationJobId, QueueEnum } from '@roombook/contract';
import { ConfirmationQueueProducer } from './confirmation-queue.producer';
import { BOOKING_ID } from './testing/booking.fixture';

describe('ConfirmationQueueProducer', () => {
  let producer: ConfirmationQueueProducer;
  let add: jest.Mock;

  beforeEach(async () => {
    add = jest.fn().mockResolvedValue({ id: confirmationJobId(BOOKING_ID) });
    const moduleRef = await Test.createTestingModule({
      providers: [
        ConfirmationQueueProducer,
        { provide: getQueueToken(QueueEnum.BOOKING_CONFIRMATION), useValue: { add } },
      ],
    }).compile();
    producer = moduleRef.get(ConfirmationQueueProducer);
  });

  afterEach(() => jest.restoreAllMocks());

  it('adds one job per booking with the contract job id and retry policy', async () => {
    await producer.enqueue(BOOKING_ID);

    expect(add).toHaveBeenCalledTimes(1);
    expect(add).toHaveBeenCalledWith(
      QueueEnum.BOOKING_CONFIRMATION,
      { bookingId: BOOKING_ID },
      { jobId: `confirmation-${BOOKING_ID}`, attempts: 3, backoff: { type: 'exponential', delay: 1000 } },
    );
  });

  it('logs a rejected add and does not rethrow it', async () => {
    const logged = jest.spyOn(Logger.prototype, 'error').mockImplementation(() => undefined);
    add.mockRejectedValue(new Error('redis is down'));

    await expect(producer.enqueue(BOOKING_ID)).resolves.toBeUndefined();
    expect(logged).toHaveBeenCalledWith(expect.stringContaining(BOOKING_ID), expect.anything());
  });
});

import { Test } from '@nestjs/testing';
import { getRepositoryToken } from '@nestjs/typeorm';
import { BookingEntity, IdempotencyKeyEntity } from '@roombook/backend-common';
import { ConfirmationStatusEnum } from '@roombook/contract';
import { DataSource } from 'typeorm';
import { CreateBookingCommand } from './dto/create-booking.command';
import { IdempotentCreateOutcomeKindEnum } from './dto/idempotent-create-outcome';
import { IdempotentBookingRepository } from './idempotent-booking.repository';
import { bookingDto, bookingEntity, ROOM_ID } from './testing/booking.fixture';

describe('IdempotentBookingRepository', () => {
  const key = '0b9d6f1c-5a3e-4f7b-8c2d-1e0f9a8b7c6d';
  const command: CreateBookingCommand = {
    idempotencyKey: key,
    requestFingerprint: 'f'.repeat(64),
    roomId: ROOM_ID,
    title: 'Planning',
    organizerEmail: 'ana@example.com',
    startsAt: new Date('2030-01-01T10:00:00.000Z'),
    endsAt: new Date('2030-01-01T11:00:00.000Z'),
  };
  const storedKey = Object.assign(new IdempotencyKeyEntity(), {
    key,
    requestFingerprint: 'f'.repeat(64),
    responseStatus: 201,
    responseBody: bookingDto(),
  });
  let repository: IdempotentBookingRepository;
  let findKey: jest.Mock;
  let transaction: jest.Mock;
  let manager: Record<'query' | 'findOneBy' | 'create' | 'save' | 'insert', jest.Mock>;

  beforeEach(async () => {
    manager = {
      query: jest.fn().mockResolvedValue([{ locked: true }]),
      findOneBy: jest.fn().mockResolvedValue(null),
      create: jest.fn((_entity: unknown, values: Partial<BookingEntity>) => values),
      save: jest.fn().mockResolvedValue(bookingEntity()),
      insert: jest.fn().mockResolvedValue({}),
    };
    transaction = jest.fn((work: (entityManager: typeof manager) => unknown) => work(manager));
    findKey = jest.fn();
    const moduleRef = await Test.createTestingModule({
      providers: [
        IdempotentBookingRepository,
        { provide: DataSource, useValue: { transaction } },
        { provide: getRepositoryToken(IdempotencyKeyEntity), useValue: { findOneBy: findKey } },
      ],
    }).compile();
    repository = moduleRef.get(IdempotentBookingRepository);
  });

  it('finds a stored key', async () => {
    findKey.mockResolvedValue(storedKey);

    await expect(repository.findByKey(key)).resolves.toBe(storedKey);
    expect(findKey).toHaveBeenCalledWith({ key });
  });

  it('returns null for a key that was never stored', async () => {
    findKey.mockResolvedValue(null);

    await expect(repository.findByKey(key)).resolves.toBeNull();
  });

  it('stores the booking and its key in one transaction and answers created', async () => {
    const outcome = await repository.create(command);

    expect(transaction).toHaveBeenCalledTimes(1);
    expect(manager.query).toHaveBeenCalledWith(expect.stringContaining('pg_try_advisory_xact_lock'), [key]);
    expect(manager.findOneBy).toHaveBeenCalledWith(IdempotencyKeyEntity, { key });
    expect(manager.save).toHaveBeenCalledWith(BookingEntity, {
      roomId: ROOM_ID,
      title: 'Planning',
      organizerEmail: 'ana@example.com',
      startsAt: command.startsAt,
      endsAt: command.endsAt,
      confirmationStatus: ConfirmationStatusEnum.PENDING,
      confirmationAttempts: 0,
    });
    expect(manager.insert).toHaveBeenCalledWith(IdempotencyKeyEntity, {
      key,
      requestFingerprint: command.requestFingerprint,
      responseStatus: 201,
      responseBody: bookingDto(),
    });
    expect(outcome).toEqual({ kind: IdempotentCreateOutcomeKindEnum.CREATED, booking: bookingDto() });
  });

  it('takes the lock, reads the key, stores the booking and then the key, in that order', async () => {
    await repository.create(command);

    const [lock] = manager.query.mock.invocationCallOrder;
    const [read] = manager.findOneBy.mock.invocationCallOrder;
    const [booking] = manager.save.mock.invocationCallOrder;
    const [keyRow] = manager.insert.mock.invocationCallOrder;
    expect([lock, read, booking, keyRow]).toEqual([lock, read, booking, keyRow].sort((a, b) => a - b));
  });

  it('answers in progress and stores nothing when the lock is held', async () => {
    manager.query.mockResolvedValue([{ locked: false }]);

    await expect(repository.create(command)).resolves.toEqual({ kind: IdempotentCreateOutcomeKindEnum.IN_PROGRESS });
    expect(manager.findOneBy).not.toHaveBeenCalled();
    expect(manager.save).not.toHaveBeenCalled();
    expect(manager.insert).not.toHaveBeenCalled();
  });

  it('answers existing with the stored key and stores nothing when the key is already there', async () => {
    manager.findOneBy.mockResolvedValue(storedKey);

    await expect(repository.create(command)).resolves.toEqual({
      kind: IdempotentCreateOutcomeKindEnum.EXISTING,
      storedKey,
    });
    expect(manager.save).not.toHaveBeenCalled();
    expect(manager.insert).not.toHaveBeenCalled();
  });

  it('rejects, so the transaction rolls back, when the key row cannot be stored', async () => {
    manager.insert.mockRejectedValue(new Error('duplicate key value violates unique constraint'));

    await expect(repository.create(command)).rejects.toThrow('duplicate key');
  });
});

import { Test } from '@nestjs/testing';
import { IdempotencyKeyEntity } from '@roombook/backend-common';
import { ConfirmationStatusEnum, CreateBookingMessageDto, ErrorCodeEnum } from '@roombook/contract';
import { BookingFingerprintUtil } from './booking-fingerprint.util';
import { BookingRepository } from './booking.repository';
import { BookingService } from './booking.service';
import { BookingValidator } from './booking.validator';
import { ConfirmationQueueProducer } from './confirmation-queue.producer';
import { IdempotentCreateOutcomeKindEnum } from './dto/idempotent-create-outcome';
import { IdempotentBookingRepository } from './idempotent-booking.repository';
import { RoomLookupClient } from './room-lookup.client';
import { BOOKING_ID, bookingDto, ROOM_ID, rpcErrorOf } from './testing/booking.fixture';

describe('BookingService.createBooking', () => {
  const idempotencyKey = '0b9d6f1c-5a3e-4f7b-8c2d-1e0f9a8b7c6d';
  const message: CreateBookingMessageDto = {
    idempotencyKey,
    booking: {
      roomId: ROOM_ID,
      title: 'Planning',
      organizerEmail: 'ana@example.com',
      startsAt: '2030-01-01T12:00:00+02:00',
      endsAt: '2030-01-01T11:00:00',
    },
  };
  const requestFingerprint = BookingFingerprintUtil.of(message.booking);
  const storedKey = (fingerprint: string): IdempotencyKeyEntity =>
    Object.assign(new IdempotencyKeyEntity(), {
      key: idempotencyKey,
      requestFingerprint: fingerprint,
      responseStatus: 201,
      responseBody: bookingDto(),
    });
  let service: BookingService;
  let findByKey: jest.Mock;
  let create: jest.Mock;
  let assertRoomExists: jest.Mock;
  let enqueue: jest.Mock;

  beforeEach(async () => {
    findByKey = jest.fn().mockResolvedValue(null);
    create = jest.fn().mockResolvedValue({ kind: IdempotentCreateOutcomeKindEnum.CREATED, booking: bookingDto() });
    assertRoomExists = jest.fn().mockResolvedValue(undefined);
    enqueue = jest.fn().mockResolvedValue(undefined);
    const moduleRef = await Test.createTestingModule({
      providers: [
        BookingService,
        BookingValidator,
        { provide: BookingRepository, useValue: {} },
        { provide: IdempotentBookingRepository, useValue: { findByKey, create } },
        { provide: RoomLookupClient, useValue: { assertRoomExists } },
        { provide: ConfirmationQueueProducer, useValue: { enqueue } },
      ],
    }).compile();
    service = moduleRef.get(BookingService);
  });

  it('creates the booking, enqueues one confirmation and answers replayed false', async () => {
    await expect(service.createBooking(message)).resolves.toEqual({ booking: bookingDto(), replayed: false });

    expect(findByKey).toHaveBeenCalledWith(idempotencyKey);
    expect(assertRoomExists).toHaveBeenCalledWith(ROOM_ID);
    expect(create).toHaveBeenCalledWith({
      idempotencyKey,
      requestFingerprint,
      roomId: ROOM_ID,
      title: 'Planning',
      organizerEmail: 'ana@example.com',
      startsAt: new Date('2030-01-01T10:00:00.000Z'),
      endsAt: new Date('2030-01-01T11:00:00.000Z'),
    });
    expect(enqueue).toHaveBeenCalledTimes(1);
    expect(enqueue).toHaveBeenCalledWith(BOOKING_ID);
  });

  it('reads the key, then asks for the room, then stores, then enqueues', async () => {
    await service.createBooking(message);

    const order = [findByKey, assertRoomExists, create, enqueue].map((mock) => mock.mock.invocationCallOrder[0]);
    expect(order).toEqual([...order].sort((a, b) => a - b));
  });

  it('replays the stored body from the fast path without asking for the room', async () => {
    findByKey.mockResolvedValue(storedKey(requestFingerprint));

    await expect(service.createBooking(message)).resolves.toEqual({ booking: bookingDto(), replayed: true });
    expect(assertRoomExists).not.toHaveBeenCalled();
    expect(create).not.toHaveBeenCalled();
    expect(enqueue).not.toHaveBeenCalled();
  });

  it('replays the body first answered, not the current state of the booking', async () => {
    findByKey.mockResolvedValue(storedKey(requestFingerprint));

    const result = await service.createBooking(message);

    expect(result.booking.confirmationStatus).toBe(ConfirmationStatusEnum.PENDING);
    expect(result.booking.confirmationAttempts).toBe(0);
  });

  it('replays the stored body when the repository finds the key, without enqueueing', async () => {
    create.mockResolvedValue({
      kind: IdempotentCreateOutcomeKindEnum.EXISTING,
      storedKey: storedKey(requestFingerprint),
    });

    await expect(service.createBooking(message)).resolves.toEqual({ booking: bookingDto(), replayed: true });
    expect(enqueue).not.toHaveBeenCalled();
  });

  it.each([
    ['the fast path', (): unknown => findByKey.mockResolvedValue(storedKey('0'.repeat(64)))],
    [
      'the repository',
      (): unknown =>
        create.mockResolvedValue({
          kind: IdempotentCreateOutcomeKindEnum.EXISTING,
          storedKey: storedKey('0'.repeat(64)),
        }),
    ],
  ])('raises 422 UNPROCESSABLE.IDEMPOTENCY_KEY_REUSED for a different fingerprint from %s', async (_case, arrange) => {
    arrange();

    expect(await rpcErrorOf(() => service.createBooking(message))).toEqual(
      expect.objectContaining({ statusCode: 422, errorCode: ErrorCodeEnum.IDEMPOTENCY_KEY_REUSED }),
    );
    expect(enqueue).not.toHaveBeenCalled();
  });

  it('raises 409 CONFLICT.IDEMPOTENCY_IN_PROGRESS while the key is being stored', async () => {
    create.mockResolvedValue({ kind: IdempotentCreateOutcomeKindEnum.IN_PROGRESS });

    expect(await rpcErrorOf(() => service.createBooking(message))).toEqual(
      expect.objectContaining({ statusCode: 409, errorCode: ErrorCodeEnum.IDEMPOTENCY_IN_PROGRESS }),
    );
    expect(enqueue).not.toHaveBeenCalled();
  });

  it.each([
    ['endsAt equal to startsAt', { endsAt: '2030-01-01T10:00:00Z' }],
    ['endsAt earlier than startsAt', { endsAt: '2030-01-01T09:00:00Z' }],
    ['a time that is not an instant', { startsAt: '2030-W01-1' }],
  ])('raises 400 BAD_REQUEST.VALIDATION for %s before any key read', async (_case, change) => {
    const invalid = { idempotencyKey, booking: { ...message.booking, ...change } };

    expect(await rpcErrorOf(() => service.createBooking(invalid))).toEqual(
      expect.objectContaining({ statusCode: 400, errorCode: ErrorCodeEnum.VALIDATION }),
    );
    expect(findByKey).not.toHaveBeenCalled();
    expect(assertRoomExists).not.toHaveBeenCalled();
    expect(create).not.toHaveBeenCalled();
  });

  it('lets 404 NOT_FOUND.ROOM pass with nothing stored and nothing enqueued', async () => {
    const roomNotFound = { statusCode: 404, errorCode: ErrorCodeEnum.ROOM_NOT_FOUND, message: 'x' };
    assertRoomExists.mockRejectedValue(roomNotFound);

    await expect(service.createBooking(message)).rejects.toBe(roomNotFound);
    expect(create).not.toHaveBeenCalled();
    expect(enqueue).not.toHaveBeenCalled();
  });
});

