import { CreateBookingDto } from '@roombook/contract';
import { createHash } from 'crypto';

export class BookingFingerprintUtil {
  static of(booking: CreateBookingDto): string {
    const fields = [booking.roomId, booking.title, booking.organizerEmail, booking.startsAt, booking.endsAt];
    return createHash('sha256').update(JSON.stringify(fields)).digest('hex');
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import { ExceptionHelper, isErrorResponse, NATS_CLIENT, NatsRequestUtil } from '@roombook/backend-common';
import { ErrorCodeEnum, RoomDto, RoomIdMessageDto, RoomPatternEnum } from '@roombook/contract';

@Injectable()
export class RoomLookupClient {
  constructor(@Inject(NATS_CLIENT) private readonly client: ClientProxy) {}

  async assertRoomExists(roomId: string): Promise<void> {
    try {
      await NatsRequestUtil.send<RoomDto, RoomIdMessageDto>(this.client, RoomPatternEnum.FIND_BY_ID, { id: roomId });
    } catch (error) {
      // An error answered by another service arrives as a plain object, not an RpcException.
      if (isErrorResponse(error) && error.errorCode === ErrorCodeEnum.ROOM_NOT_FOUND) {
        ExceptionHelper.notFound(ErrorCodeEnum.ROOM_NOT_FOUND, error.message);
      }
      throw error;
    }
  }
}

import { InjectQueue } from '@nestjs/bullmq';
import { Injectable, Logger } from '@nestjs/common';
import {
  CONFIRMATION_BACKOFF_MS,
  CONFIRMATION_JOB_ATTEMPTS,
  ConfirmationJobDto,
  confirmationJobId,
  QueueEnum,
} from '@roombook/contract';
import { Queue } from 'bullmq';

@Injectable()
export class ConfirmationQueueProducer {
  private readonly logger = new Logger(ConfirmationQueueProducer.name);

  constructor(@InjectQueue(QueueEnum.BOOKING_CONFIRMATION) private readonly queue: Queue<ConfirmationJobDto>) {}

  async enqueue(bookingId: string): Promise<void> {
    try {
      await this.queue.add(
        QueueEnum.BOOKING_CONFIRMATION,
        { bookingId },
        {
          jobId: confirmationJobId(bookingId),
          attempts: CONFIRMATION_JOB_ATTEMPTS,
          backoff: { type: 'exponential', delay: CONFIRMATION_BACKOFF_MS },
        },
      );
    } catch (error) {
      this.logger.error(`Confirmation job for booking ${bookingId} was not enqueued`, error);
    }
  }
}

export class CreateBookingCommand {
  idempotencyKey: string;
  requestFingerprint: string;
  roomId: string;
  title: string;
  organizerEmail: string;
  startsAt: Date;
  endsAt: Date;
}

import { IdempotencyKeyEntity } from '@roombook/backend-common';
import { BookingDto } from '@roombook/contract';

export enum IdempotentCreateOutcomeKindEnum {
  CREATED = 'CREATED',
  EXISTING = 'EXISTING',
  IN_PROGRESS = 'IN_PROGRESS',
}

export type IdempotentCreateOutcome =
  | { kind: IdempotentCreateOutcomeKindEnum.CREATED; booking: BookingDto }
  | { kind: IdempotentCreateOutcomeKindEnum.EXISTING; storedKey: IdempotencyKeyEntity }
  | { kind: IdempotentCreateOutcomeKindEnum.IN_PROGRESS };

import { HttpStatus, Injectable } from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { BookingEntity, IdempotencyKeyEntity } from '@roombook/backend-common';
import { ConfirmationStatusEnum } from '@roombook/contract';
import { DataSource, EntityManager, Repository } from 'typeorm';
import { BookingMapper } from './booking.mapper';
import { CreateBookingCommand } from './dto/create-booking.command';
import { IdempotentCreateOutcome, IdempotentCreateOutcomeKindEnum } from './dto/idempotent-create-outcome';

type AdvisoryLockRow = { locked: boolean };

const TRY_KEY_LOCK_SQL = 'SELECT pg_try_advisory_xact_lock(hashtextextended($1, 0)) AS "locked"';

@Injectable()
export class IdempotentBookingRepository {
  constructor(
    private readonly dataSource: DataSource,
    @InjectRepository(IdempotencyKeyEntity) private readonly keys: Repository<IdempotencyKeyEntity>,
  ) {}

  findByKey(key: string): Promise<IdempotencyKeyEntity | null> {
    return this.keys.findOneBy({ key });
  }

  create(command: CreateBookingCommand): Promise<IdempotentCreateOutcome> {
    return this.dataSource.transaction((manager) => this.createLocked(manager, command));
  }

  private async createLocked(manager: EntityManager, command: CreateBookingCommand): Promise<IdempotentCreateOutcome> {
    const { idempotencyKey: key, requestFingerprint, ...values } = command;
    const [lock] = await manager.query<AdvisoryLockRow[]>(TRY_KEY_LOCK_SQL, [key]);
    if (!lock.locked) {
      return { kind: IdempotentCreateOutcomeKindEnum.IN_PROGRESS };
    }
    const storedKey = await manager.findOneBy(IdempotencyKeyEntity, { key });
    if (storedKey) {
      return { kind: IdempotentCreateOutcomeKindEnum.EXISTING, storedKey };
    }
    const entity = manager.create(BookingEntity, {
      ...values,
      confirmationStatus: ConfirmationStatusEnum.PENDING,
      confirmationAttempts: 0,
    });
    const booking = BookingMapper.toDto(await manager.save(BookingEntity, entity));
    await manager.insert(IdempotencyKeyEntity, {
      key,
      requestFingerprint,
      responseStatus: HttpStatus.CREATED,
      responseBody: booking,
    });
    return { kind: IdempotentCreateOutcomeKindEnum.CREATED, booking };
  }
}

