import { RpcException } from '@nestjs/microservices';
import { EmptyResponseException } from '@nestjs/microservices/errors/empty-response.exception';
import { Test } from '@nestjs/testing';
import { NATS_CLIENT } from '@roombook/backend-common';
import { BookingPatternEnum, ConfirmationStatusEnum, ErrorCodeEnum } from '@roombook/contract';
import { of, throwError } from 'rxjs';
import { BookingClient } from './booking.client';

describe('BookingClient', () => {
  const bookingId = '7d9f3c1e-2b4a-4c8d-9e6f-0a1b2c3d4e5f';
  let client: BookingClient;
  let send: jest.Mock;

  beforeEach(async () => {
    send = jest.fn();
    const moduleRef = await Test.createTestingModule({
      providers: [BookingClient, { provide: NATS_CLIENT, useValue: { send } }],
    }).compile();
    client = moduleRef.get(BookingClient);
  });

  it('finds the booking through the booking service', async () => {
    const booking = { id: bookingId, organizerEmail: 'ana@example.com' };
    send.mockReturnValue(of(booking));

    await expect(client.findBooking(bookingId)).resolves.toBe(booking);
    expect(send).toHaveBeenCalledWith(BookingPatternEnum.FIND_BY_ID, { id: bookingId });
  });

  it('returns null when the booking service answers NOT_FOUND.BOOKING', async () => {
    send.mockReturnValue(
      throwError(() => ({ statusCode: 404, errorCode: ErrorCodeEnum.BOOKING_NOT_FOUND, message: 'gone' })),
    );

    await expect(client.findBooking(bookingId)).resolves.toBeNull();
  });

  it('rethrows another error answered by the booking service', async () => {
    const relayed = { status: 'error', message: 'Internal server error' };
    send.mockReturnValue(throwError(() => relayed));

    await expect(client.findBooking(bookingId)).rejects.toBe(relayed);
  });

  it('rethrows 503 UNAVAILABLE.SERVICE when the booking service does not answer', async () => {
    send.mockReturnValue(throwError(() => new EmptyResponseException(BookingPatternEnum.FIND_BY_ID)));

    const error = await client.findBooking(bookingId).catch((caught: unknown) => caught);

    expect(error).toBeInstanceOf(RpcException);
    expect((error as RpcException).getError()).toEqual(
      expect.objectContaining({ statusCode: 503, errorCode: ErrorCodeEnum.SERVICE_UNAVAILABLE }),
    );
  });

  it('reports an outcome to the record confirmation pattern', async () => {
    const outcome = { bookingId, status: ConfirmationStatusEnum.SENT, attempts: 3 };
    send.mockReturnValue(of(true));

    await expect(client.reportOutcome(outcome)).resolves.toBeUndefined();
    expect(send).toHaveBeenCalledWith(BookingPatternEnum.RECORD_CONFIRMATION, outcome);
  });

  it('rejects when the outcome cannot be reported', async () => {
    send.mockReturnValue(throwError(() => new EmptyResponseException(BookingPatternEnum.RECORD_CONFIRMATION)));

    await expect(
      client.reportOutcome({ bookingId, status: ConfirmationStatusEnum.SENT, attempts: 1 }),
    ).rejects.toBeInstanceOf(RpcException);
  });
});

import { Test } from '@nestjs/testing';
import { BookingDto, ConfirmationStatusEnum } from '@roombook/contract';
import { BookingClient } from './booking.client';
import { ConfirmationService } from './confirmation.service';
import { SimulatedConfirmationSender } from './simulated-confirmation.sender';

describe('ConfirmationService.confirm', () => {
  const bookingId = '7d9f3c1e-2b4a-4c8d-9e6f-0a1b2c3d4e5f';
  const bookingOf = (organizerEmail: string, overrides: Partial<BookingDto> = {}): BookingDto => ({
    id: bookingId,
    roomId: '3f0c1a52-8f0b-4c59-9a6e-1d2b7c9e4a10',
    title: 'Planning',
    organizerEmail,
    startsAt: '2030-01-01T10:00:00.000Z',
    endsAt: '2030-01-01T11:00:00.000Z',
    confirmationStatus: ConfirmationStatusEnum.PENDING,
    confirmationAttempts: 0,
    createdAt: '2029-12-01T09:00:00.000Z',
    updatedAt: '2029-12-01T09:00:00.000Z',
    ...overrides,
  });
  let service: ConfirmationService;
  let findBooking: jest.Mock;
  let reportOutcome: jest.Mock;
  let deliver: jest.SpyInstance;

  beforeEach(async () => {
    findBooking = jest.fn();
    reportOutcome = jest.fn().mockResolvedValue(undefined);
    const moduleRef = await Test.createTestingModule({
      providers: [
        ConfirmationService,
        SimulatedConfirmationSender,
        { provide: BookingClient, useValue: { findBooking, reportOutcome } },
      ],
    }).compile();
    service = moduleRef.get(ConfirmationService);
    deliver = jest.spyOn(moduleRef.get(SimulatedConfirmationSender), 'deliver');
  });

  it('reports SENT with 1 attempt for an ordinary address and resolves', async () => {
    findBooking.mockResolvedValue(bookingOf('ana@example.com'));

    await expect(service.confirm(bookingId, 1)).resolves.toBeUndefined();
    expect(findBooking).toHaveBeenCalledWith(bookingId);
    expect(deliver).toHaveBeenCalledWith('ana@example.com', 1);
    expect(reportOutcome).toHaveBeenCalledTimes(1);
    expect(reportOutcome).toHaveBeenCalledWith({ bookingId, status: ConfirmationStatusEnum.SENT, attempts: 1 });
  });

  it.each([1, 2])('reports PENDING with attempt %i for a retry address and rejects', async (attempt) => {
    findBooking.mockResolvedValue(bookingOf('ana@retry.example', { confirmationAttempts: attempt - 1 }));

    await expect(service.confirm(bookingId, attempt)).rejects.toThrow(`attempt ${attempt}`);
    expect(reportOutcome).toHaveBeenCalledWith({ bookingId, status: ConfirmationStatusEnum.PENDING, attempts: attempt });
  });

  it('reports SENT with 3 attempts for a retry address on attempt 3 and resolves', async () => {
    findBooking.mockResolvedValue(bookingOf('ana@retry.example', { confirmationAttempts: 2 }));

    await expect(service.confirm(bookingId, 3)).resolves.toBeUndefined();
    expect(reportOutcome).toHaveBeenCalledWith({ bookingId, status: ConfirmationStatusEnum.SENT, attempts: 3 });
  });

  it.each(['ana@bounce.example', 'ana@BOUNCE.EXAMPLE'])(
    'reports FAILED with 3 attempts for %s on attempt 3 and rejects',
    async (organizerEmail) => {
      findBooking.mockResolvedValue(bookingOf(organizerEmail, { confirmationAttempts: 2 }));

      await expect(service.confirm(bookingId, 3)).rejects.toThrow('attempt 3');
      expect(reportOutcome).toHaveBeenCalledWith({ bookingId, status: ConfirmationStatusEnum.FAILED, attempts: 3 });
    },
  );

  it('reports PENDING, not FAILED, for a bounce address before the last attempt', async () => {
    findBooking.mockResolvedValue(bookingOf('ana@bounce.example'));

    await expect(service.confirm(bookingId, 1)).rejects.toThrow('attempt 1');
    expect(reportOutcome).toHaveBeenCalledWith({ bookingId, status: ConfirmationStatusEnum.PENDING, attempts: 1 });
  });

  it('resolves without sending or reporting when the booking no longer exists', async () => {
    findBooking.mockResolvedValue(null);

    await expect(service.confirm(bookingId, 2)).resolves.toBeUndefined();
    expect(deliver).not.toHaveBeenCalled();
    expect(reportOutcome).not.toHaveBeenCalled();
  });

  it.each([ConfirmationStatusEnum.SENT, ConfirmationStatusEnum.FAILED])(
    'resolves without sending or reporting when the booking is already %s',
    async (confirmationStatus) => {
      findBooking.mockResolvedValue(bookingOf('ana@bounce.example', { confirmationStatus, confirmationAttempts: 1 }));

      await expect(service.confirm(bookingId, 1)).resolves.toBeUndefined();
      expect(deliver).not.toHaveBeenCalled();
      expect(reportOutcome).not.toHaveBeenCalled();
    },
  );

  it('reports the identical outcome when the same attempt runs twice', async () => {
    findBooking.mockResolvedValue(bookingOf('ana@retry.example', { confirmationAttempts: 1 }));

    await expect(service.confirm(bookingId, 1)).rejects.toThrow();
    await expect(service.confirm(bookingId, 1)).rejects.toThrow();

    expect(reportOutcome).toHaveBeenCalledTimes(2);
    expect(reportOutcome.mock.calls[1]).toEqual(reportOutcome.mock.calls[0]);
  });

  it('rejects without sending when the booking cannot be read, so the job is retried', async () => {
    findBooking.mockRejectedValue(new Error('booking service is down'));

    await expect(service.confirm(bookingId, 1)).rejects.toThrow('booking service is down');
    expect(deliver).not.toHaveBeenCalled();
    expect(reportOutcome).not.toHaveBeenCalled();
  });
});

import { Test } from '@nestjs/testing';
import { ConfirmationJobDto } from '@roombook/contract';
import { Job } from 'bullmq';
import { ConfirmationProcessor } from './confirmation.processor';
import { ConfirmationService } from './confirmation.service';

describe('ConfirmationProcessor', () => {
  const bookingId = '7d9f3c1e-2b4a-4c8d-9e6f-0a1b2c3d4e5f';
  const jobWith = (attemptsMade: number): Job<ConfirmationJobDto> =>
    ({ data: { bookingId }, attemptsMade }) as Job<ConfirmationJobDto>;
  let processor: ConfirmationProcessor;
  let confirm: jest.Mock;

  beforeEach(async () => {
    confirm = jest.fn().mockResolvedValue(undefined);
    const moduleRef = await Test.createTestingModule({
      providers: [ConfirmationProcessor, { provide: ConfirmationService, useValue: { confirm } }],
    }).compile();
    processor = moduleRef.get(ConfirmationProcessor);
  });

  it.each([
    [0, 1],
    [1, 2],
    [2, 3],
  ])('delegates a job with %i attempts made as attempt %i', async (attemptsMade, attempt) => {
    await expect(processor.process(jobWith(attemptsMade))).resolves.toBeUndefined();
    expect(confirm).toHaveBeenCalledWith(bookingId, attempt);
  });

  it('rejects when the confirmation was not delivered, so BullMQ retries or fails the job', async () => {
    confirm.mockRejectedValue(new Error('not delivered'));

    await expect(processor.process(jobWith(0))).rejects.toThrow('not delivered');
  });
});

import { Injectable } from '@nestjs/common';
import { BOUNCE_EMAIL_DOMAIN, CONFIRMATION_JOB_ATTEMPTS, RETRY_EMAIL_DOMAIN } from '@roombook/contract';

@Injectable()
export class SimulatedConfirmationSender {
  deliver(organizerEmail: string, attempt: number): boolean {
    const address = organizerEmail.toLowerCase();
    if (address.endsWith(`@${BOUNCE_EMAIL_DOMAIN}`)) {
      return false;
    }
    if (address.endsWith(`@${RETRY_EMAIL_DOMAIN}`)) {
      return attempt >= CONFIRMATION_JOB_ATTEMPTS;
    }
    return true;
  }
}

import { Inject, Injectable } from '@nestjs/common';
import { ClientProxy } from '@nestjs/microservices';
import { isErrorResponse, NATS_CLIENT, NatsRequestUtil } from '@roombook/backend-common';
import {
  BookingDto,
  BookingIdMessageDto,
  BookingPatternEnum,
  ErrorCodeEnum,
  RecordConfirmationResultDto,
} from '@roombook/contract';

@Injectable()
export class BookingClient {
  constructor(@Inject(NATS_CLIENT) private readonly client: ClientProxy) {}

  async findBooking(bookingId: string): Promise<BookingDto | null> {
    try {
      return await NatsRequestUtil.send<BookingDto, BookingIdMessageDto>(this.client, BookingPatternEnum.FIND_BY_ID, {
        id: bookingId,
      });
    } catch (error) {
      if (isErrorResponse(error) && error.errorCode === ErrorCodeEnum.BOOKING_NOT_FOUND) {
        return null;
      }
      throw error;
    }
  }

  async reportOutcome(outcome: RecordConfirmationResultDto): Promise<void> {
    await NatsRequestUtil.send<boolean, RecordConfirmationResultDto>(
      this.client,
      BookingPatternEnum.RECORD_CONFIRMATION,
      outcome,
    );
  }
}

import { Injectable } from '@nestjs/common';
import { CONFIRMATION_JOB_ATTEMPTS, ConfirmationStatusEnum } from '@roombook/contract';
import { BookingClient } from './booking.client';
import { SimulatedConfirmationSender } from './simulated-confirmation.sender';

@Injectable()
export class ConfirmationService {
  constructor(
    private readonly bookingClient: BookingClient,
    private readonly sender: SimulatedConfirmationSender,
  ) {}

  async confirm(bookingId: string, attempt: number): Promise<void> {
    const booking = await this.bookingClient.findBooking(bookingId);
    if (!booking || booking.confirmationStatus !== ConfirmationStatusEnum.PENDING) {
      return;
    }
    const delivered = this.sender.deliver(booking.organizerEmail, attempt);
    await this.bookingClient.reportOutcome({
      bookingId,
      status: this.statusOf(delivered, attempt),
      attempts: attempt,
    });
    if (!delivered) {
      throw new Error(`Confirmation for booking ${bookingId} was not delivered on attempt ${attempt}`);
    }
  }

  private statusOf(delivered: boolean, attempt: number): ConfirmationStatusEnum {
    if (delivered) {
      return ConfirmationStatusEnum.SENT;
    }
    return attempt >= CONFIRMATION_JOB_ATTEMPTS ? ConfirmationStatusEnum.FAILED : ConfirmationStatusEnum.PENDING;
  }
}

import { Processor, WorkerHost } from '@nestjs/bullmq';
import { ConfirmationJobDto, QueueEnum } from '@roombook/contract';
import { Job } from 'bullmq';
import { ConfirmationService } from './confirmation.service';

@Processor(QueueEnum.BOOKING_CONFIRMATION)
export class ConfirmationProcessor extends WorkerHost {
  constructor(private readonly confirmationService: ConfirmationService) {
    super();
  }

  process(job: Job<ConfirmationJobDto>): Promise<void> {
    return this.confirmationService.confirm(job.data.bookingId, job.attemptsMade + 1);
  }
}

